SRC_FILES = {'src/__init__.py': '', 'src/data/__init__.py': '', 'src/data/load_data.py': '"""Load data FIK FAIR 2026 (regresi Anonymous Competition Score, metrik RMSE)."""\nfrom __future__ import annotations\n\nimport os\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nID, TARGET = "record_id", "target"\n\n\ndef find_data_dir(local: str | Path = "../data/raw") -> Path:\n    """Folder yang berisi train.csv kompetisi ini (di /kaggle/input, ikuti symlink)."""\n    for root, _, files in os.walk("/kaggle/input", followlinks=True):\n        if {"train.csv", "test.csv"} <= set(files):\n            if TARGET in pd.read_csv(Path(root) / "train.csv", nrows=1).columns:\n                return Path(root)\n    return Path(local)\n\n\ndef load(data_dir: str | Path):\n    d = Path(data_dir)\n    train, test = pd.read_csv(d / "train.csv"), pd.read_csv(d / "test.csv")\n    features = [c for c in train.columns if c.startswith("feature_")]\n    return train, test, features\n\n\ndef positions(n: int) -> np.ndarray:\n    """Posisi baris dalam file, dinormalisasi ke (0, 1): (i + 0,5) / n."""\n    return (np.arange(n) + 0.5) / n\n', 'src/models/__init__.py': '', 'src/models/position_prior.py': '"""Prior posisi: regresi isotonik target terhadap urutan baris, dihitung out-of-fold agar tidak bocor.\n\nMetode ini dari notebook final tim (Lomba Terakhir Bersama Abil, FIK FAIR 2026); fungsinya dipindahkan ke modul dengan\nargumen eksplisit, tanpa mengubah perhitungannya.\n"""\nfrom __future__ import annotations\n\nimport numpy as np\nfrom sklearn.isotonic import IsotonicRegression\nfrom sklearn.model_selection import KFold, RepeatedKFold\n\n\ndef prior_predict(pos_tr, y_tr, pos_q, increasing: bool) -> np.ndarray:\n    iso = IsotonicRegression(increasing=increasing, out_of_bounds="clip")\n    iso.fit(pos_tr, y_tr)\n    return iso.predict(pos_q)\n\n\ndef inner_oof_prior(idx, pos, y, seed, increasing, n_splits=5) -> np.ndarray:\n    """Prior OOF untuk baris `idx`, memakai hanya baris lain di `idx` (label residual tanpa bocor)."""\n    out = np.zeros(len(idx))\n    for a, b in KFold(n_splits=n_splits, shuffle=True, random_state=seed).split(idx):\n        out[b] = prior_predict(pos[idx[a]], y[idx[a]], pos[idx[b]], increasing)\n    return out\n\n\ndef full_oof_prior(pos, y, increasing, n_splits=10, n_repeats=5, seed=2026 + 911) -> np.ndarray:\n    s, c = np.zeros(len(y)), np.zeros(len(y))\n    for tr, va in RepeatedKFold(n_splits=n_splits, n_repeats=n_repeats, random_state=seed).split(pos):\n        s[va] += prior_predict(pos[tr], y[tr], pos[va], increasing)\n        c[va] += 1\n    return s / c\n\n\ndef block_splits(pos, n_blocks=10):\n    """Blocked CV: setiap fold menahan satu blok posisi yang utuh."""\n    g = np.floor(np.clip(pos, 0, 0.999999) * n_blocks).astype(int)\n    return [(np.where(g != b)[0], np.where(g == b)[0]) for b in range(n_blocks) if np.any(g == b)]\n', 'src/models/residual_models.py': '"""Model zoo yang mempelajari residual (target − prior posisi) dari 24 fitur, plus CV dan blending NNLS.\n\nKonfigurasi model sama dengan notebook final tim. TabPFN (opsional di notebook asli) tidak dipakai karena butuh\ninternet untuk mengunduh bobot; run final tim juga berjalan tanpa TabPFN.\n"""\nfrom __future__ import annotations\n\nimport numpy as np\nfrom scipy.optimize import nnls\nfrom sklearn.decomposition import PCA\nfrom sklearn.gaussian_process import GaussianProcessRegressor\nfrom sklearn.gaussian_process.kernels import ConstantKernel, Matern, WhiteKernel\nfrom sklearn.kernel_ridge import KernelRidge\nfrom sklearn.linear_model import Ridge\nfrom sklearn.metrics import mean_squared_error\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.svm import SVR\n\nfrom .position_prior import inner_oof_prior, prior_predict\n\nMODEL_NAMES = ["ridge", "svr_pca12", "krr_raw", "gp_ard"]\n\n\ndef rmse(a, b) -> float:\n    return float(mean_squared_error(a, b) ** 0.5)\n\n\ndef build_models(n_feat: int, seed: int = 2026) -> dict:\n    gp_kernel = (ConstantKernel(1.0, (1e-2, 1e2))\n                 * Matern(length_scale=np.full(n_feat, 3.0), length_scale_bounds=(0.3, 100.0), nu=2.5)\n                 + WhiteKernel(0.5, (1e-3, 5.0)))\n    return {\n        "ridge": Pipeline([("s", StandardScaler()), ("m", Ridge(alpha=100.0))]),\n        "svr_pca12": Pipeline([("s", StandardScaler()), ("p", PCA(n_components=min(12, n_feat), whiten=True, svd_solver="full")),\n                               ("m", SVR(kernel="rbf", C=15, gamma=0.08, epsilon=0.10))]),\n        "krr_raw": Pipeline([("s", StandardScaler()), ("m", KernelRidge(kernel="rbf", alpha=0.5, gamma=0.03))]),\n        "gp_ard": Pipeline([("s", StandardScaler()), ("m", GaussianProcessRegressor(kernel=gp_kernel, normalize_y=True,\n                                                                                 n_restarts_optimizer=0, random_state=seed))]),\n    }\n\n\ndef fit_predict_models(Xtr, ytr, Xq_list, seed=2026) -> dict:\n    out = {}\n    for name, mdl in build_models(Xtr.shape[1], seed).items():\n        mdl.fit(Xtr, ytr)\n        out[name] = [mdl.predict(Xq) for Xq in Xq_list]\n    return out\n\n\ndef run_residual_cv(splits, X, y, pos, increasing, seed=2026):\n    """Untuk setiap fold: label residual dari prior OOF di dalam fold latih, prior validasi dari seluruh fold latih."""\n    n = len(y)\n    prior_s, cnt, res_s = np.zeros(n), np.zeros(n), {}\n    for k, (tr, va) in enumerate(splits):\n        res_tr = y[tr] - inner_oof_prior(tr, pos, y, seed=seed + k, increasing=increasing)\n        prior_s[va] += prior_predict(pos[tr], y[tr], pos[va], increasing)\n        cnt[va] += 1\n        for name, (p,) in fit_predict_models(X[tr], res_tr, [X[va]], seed).items():\n            res_s.setdefault(name, np.zeros(n))[va] += p\n    return prior_s / cnt, {k: v / cnt for k, v in res_s.items()}\n\n\ndef nnls_blend(res_list: list[dict], targets: list[np.ndarray], names: list[str]) -> np.ndarray:\n    """Bobot non-negatif yang meminimalkan galat residual pada gabungan beberapa skema OOF."""\n    R = np.vstack([np.column_stack([r[n] for n in names]) for r in res_list])\n    w, _ = nnls(R, np.concatenate(targets))\n    return w\n', 'src/visualization/__init__.py': '', 'src/visualization/plots.py': '"""Gaya grafik yang konsisten dan ramah buta warna (palet Okabe–Ito)."""\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport matplotlib.pyplot as plt\nimport matplotlib.ticker as mtick\nimport seaborn as sns\n\nPALETTE = {"blue": "#0072B2", "orange": "#D55E00", "green": "#009E73", "neutral": "#8C8C8C"}\n\n\ndef set_style() -> None:\n    sns.set_theme(style="whitegrid", context="notebook", palette="colorblind")\n    plt.rcParams.update({"figure.dpi": 110, "axes.titleweight": "bold", "axes.titlesize": 12})\n\n\ndef save_fig(fig_dir: Path, name: str) -> None:\n    """Rapikan layout, simpan PNG ke `fig_dir`, lalu tampilkan."""\n    plt.tight_layout()\n    plt.savefig(Path(fig_dir) / f"{name}.png", dpi=130, bbox_inches="tight")\n    plt.show()\n\n\ndef pct_axis(ax, decimals: int = 1, axis: str = "y") -> None:\n    fmt = mtick.PercentFormatter(1, decimals=decimals)\n    (ax.yaxis if axis == "y" else ax.xaxis).set_major_formatter(fmt)\n\n\ndef ref_line(ax, value: float, label: str = "rata-rata") -> None:\n    ax.axhline(value, color=PALETTE["neutral"], ls="--", lw=1.2, label=label)\n'}
NOTEBOOK = json.loads('{\n "cells": [\n  {\n   "cell_type": "markdown",\n   "id": "6836e1e5",\n   "metadata": {},\n   "source": [\n    "# Ketika Urutan Baris Lebih Informatif daripada Fitur: Prior Posisi dan Residual Learning\\n",\n    "\\n",\n    "| | |\\n",\n    "| --- | --- |\\n",\n    "| **Kompetisi** | [Data Science Competition FIK FAIR 2026](https://www.kaggle.com/competitions/data-science-competition-fikfair2026) (UPN \\"Veteran\\" Jakarta, Kaggle, Oktober 2026) |\\n",\n    "| **Tujuan** | Memprediksi `target` (*Anonymous Competition Score*) dari 24 fitur lingkungan/iklim yang dianonimkan (metrik RMSE) |\\n",\n    "| **Data** | 382 baris latih, 96 baris uji (29 public, 67 private) |\\n",\n    "| **Tim** | **Lomba Terakhir Bersama Abil**: Muhammad Abil Hasan, Naufal Arkan Wahib, Fauzan Ahsanudin Alfikri, Salsabila Rizqiyah Anwar |\\n",\n    "| **Versi ini** | Disusun ulang oleh Fauzan Ahsanudin Alfikri · [Kaggle: fauzan2](https://www.kaggle.com/fauzan2), November 2026 |\\n",\n    "| **Lingkungan** | Dijalankan penuh di Kaggle (CPU) |\\n",\n    "\\n",\n    "Metode dan konfigurasi model berasal dari notebook final tim selama kompetisi. Versi ini mempertahankan metode itu\\n",\n    "apa adanya, lalu menambahkan EDA, bukti visual, dan pembahasan hasil leaderboard.\\n",\n    "\\n",\n    "**Pertanyaan penelitian.** Fitur yang dianonimkan hampir tidak berkorelasi dengan target, tetapi target tersusun hampir\\n",\n    "monoton terhadap urutan baris file. Apakah urutan itu bisa dipakai dengan aman, dan seberapa banyak yang masih bisa\\n",\n    "ditambahkan oleh 24 fitur?\\n",\n    "\\n",\n    "**Ringkasan temuan.**\\n",\n    "- Target tersusun hampir monoton menurun terhadap urutan baris di `train.csv` (Spearman −0,981), sedangkan fitur terkuat hanya berkorelasi 0,42 dengan target. `record_id` acak, jadi informasinya ada di urutan file.\\n",\n    "- Korelasi setiap fitur dengan target hampir persis cermin korelasinya dengan posisi baris (korelasi antar keduanya −0,999): fitur \\"tahu\\" target hanya sejauh fitur itu ikut tersusun menurut urutan.\\n",\n    "- Test tampaknya disusun dengan urutan yang sama: model yang hanya memakai fitur menghasilkan prediksi test yang menurun terhadap urutan baris test (Spearman −0,75, train −0,80), dan adversarial AUC train vs test hanya 0,547.\\n",\n    "- Metode tim, **prior posisi isotonik + koreksi residual dari 24 fitur** (blend GP-ARD dan SVR, diredam 0,7×), mencapai RMSE random CV **2,394** dan blocked CV **4,308**, dibanding 2,966 / 4,429 untuk prior saja dan 8,478 untuk model tanpa posisi.\\n",\n    "- Di leaderboard, submission ini (identik dengan submission tim 4 Oktober 2026) mendapat public **2,248** tetapi private **3,081**. Tim finis peringkat 4 dari 13; submission tim dengan private terbaik (2,835) memakai varian lain dengan skor public lebih buruk.\\n",\n    "\\n",\n    "**Alur:** 1. Setup → 2. Memahami data → 3. EDA → 4. Desain validasi → 5. Baseline → 6. Residual learning →\\n",\n    "7. Blending dan skala koreksi → 8. Diagnostik → 9. Submission → 10. Kesimpulan"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "5d131954",\n   "metadata": {},\n   "source": [\n    "## 1. Setup\\n",\n    "\\n",\n    "Semua parameter ada di sel ini, dengan nilai yang sama seperti notebook final tim. Prior posisi ada di\\n",\n    "`src/models/position_prior.py`, model residual dan blending di `src/models/residual_models.py`."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "779e3f8a",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import os\\n",\n    "import shutil\\n",\n    "import sys\\n",\n    "import time\\n",\n    "import warnings\\n",\n    "from importlib.metadata import version\\n",\n    "from pathlib import Path\\n",\n    "\\n",\n    "import numpy as np\\n",\n    "import pandas as pd\\n",\n    "import matplotlib.pyplot as plt\\n",\n    "import seaborn as sns\\n",\n    "from scipy.optimize import nnls\\n",\n    "from scipy.stats import spearmanr\\n",\n    "from sklearn.ensemble import RandomForestClassifier\\n",\n    "from sklearn.model_selection import KFold, RepeatedKFold, StratifiedKFold, cross_val_predict\\n",\n    "from sklearn.metrics import roc_auc_score\\n",\n    "\\n",\n    "SRC_ROOT = Path.cwd().parent\\n",\n    "for r, _, f in os.walk(\\"/kaggle/input\\", followlinks=True):\\n",\n    "    if Path(r).name == \\"models\\" and \\"position_prior.py\\" in f:\\n",\n    "        pkg = Path(r).parent\\n",\n    "        if pkg.name == \\"src\\":\\n",\n    "            SRC_ROOT = pkg.parent\\n",\n    "        else:\\n",\n    "            SRC_ROOT = Path(\\"/tmp/project\\")\\n",\n    "            shutil.copytree(pkg, SRC_ROOT / \\"src\\", dirs_exist_ok=True)\\n",\n    "        break\\n",\n    "sys.path.insert(0, str(SRC_ROOT))\\n",\n    "from src.data.load_data import ID, TARGET, find_data_dir, load, positions\\n",\n    "from src.models.position_prior import block_splits, full_oof_prior, prior_predict\\n",\n    "from src.models.residual_models import MODEL_NAMES, fit_predict_models, nnls_blend, rmse, run_residual_cv\\n",\n    "from src.visualization.plots import PALETTE, save_fig, set_style\\n",\n    "\\n",\n    "# ── Parameter (sama dengan notebook final tim)\\n",\n    "SEED = 2026\\n",\n    "N_BLOCKS = 10                          # blocked CV\\n",\n    "RANDOM_SPLITS, RANDOM_REPEATS = 8, 2   # random repeated CV\\n",\n    "SCALES = np.round(np.arange(0.0, 1.21, 0.1), 2)\\n",\n    "\\n",\n    "# ── Path\\n",\n    "DATA_DIR = find_data_dir(local=\\"../data/raw\\")\\n",\n    "OUT_DIR = Path(\\"/kaggle/working\\") if Path(\\"/kaggle/working\\").exists() else Path(\\"../reports\\")\\n",\n    "FIG_DIR = OUT_DIR / \\"figures\\"\\n",\n    "FIG_DIR.mkdir(parents=True, exist_ok=True)\\n",\n    "\\n",\n    "warnings.filterwarnings(\\"ignore\\")\\n",\n    "np.random.seed(SEED)\\n",\n    "set_style()\\n",\n    "C1, C2, C3, CN = PALETTE[\\"blue\\"], PALETTE[\\"orange\\"], PALETTE[\\"green\\"], PALETTE[\\"neutral\\"]\\n",\n    "T0 = time.time()\\n",\n    "print(\\"DATA_DIR:\\", DATA_DIR, \\"| OUT_DIR:\\", OUT_DIR)"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "b0f79ebd",\n   "metadata": {},\n   "source": [\n    "## 2. Memahami data\\n",\n    "\\n",\n    "Setiap baris punya `record_id` acak, 24 fitur numerik yang sudah ditransformasi, dan `target` di data latih."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "9104a810",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "train, test, FEATURES = load(DATA_DIR)\\n",\n    "X, X_test = train[FEATURES].to_numpy(float), test[FEATURES].to_numpy(float)\\n",\n    "y = train[TARGET].to_numpy(float)\\n",\n    "n_train, n_test = len(train), len(test)\\n",\n    "pos, pos_test = positions(n_train), positions(n_test)\\n",\n    "ids = train[ID].str[1:].astype(int)\\n",\n    "print(f\\"train {train.shape} | test {test.shape} | nilai kosong: {int(train.isna().sum().sum() + test.isna().sum().sum())}\\")\\n",\n    "print(f\\"target: rata-rata {y.mean():.2f}, std {y.std():.2f}, rentang {y.min():.2f}–{y.max():.2f}, skewness {pd.Series(y).skew():.2f}\\")\\n",\n    "print(f\\"Spearman(record_id, target) = {spearmanr(ids, y).correlation:.3f} -> record_id tidak membawa informasi urutan\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "ededf3c0",\n   "metadata": {},\n   "source": [\n    "**Temuan.** 382 baris latih dan 96 baris uji, tanpa nilai kosong. Target berkisar 32,6–100,4 dengan ekor kanan (skewness 0,75). Nomor pada `record_id` tidak berhubungan dengan target (Spearman 0,05), jadi ID sudah diacak panitia."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "e285ccca",\n   "metadata": {},\n   "source": [\n    "## 3. EDA\\n",\n    "\\n",\n    "### 3.1 Target tersusun menurut urutan baris"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "5beb677e",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "rho_pos = spearmanr(pos, y).correlation\\n",\n    "INCREASING = bool(rho_pos > 0)\\n",\n    "prior_in = prior_predict(pos, y, pos, INCREASING)\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(13, 4.2))\\n",\n    "ax[0].scatter(np.arange(n_train), y, s=12, color=C1, alpha=0.7, label=\\"target\\")\\n",\n    "ax[0].plot(np.arange(n_train), prior_in, color=C2, lw=2, label=\\"regresi isotonik (menurun)\\")\\n",\n    "ax[0].set(xlabel=\\"urutan baris di train.csv\\", ylabel=\\"target\\", title=f\\"Target vs urutan baris (Spearman {rho_pos:.3f})\\"); ax[0].legend()\\n",\n    "ax[1].hist(y, bins=40, color=C1, alpha=0.8)\\n",\n    "ax[1].set(xlabel=\\"target\\", ylabel=\\"jumlah baris\\", title=\\"Distribusi target\\")\\n",\n    "save_fig(FIG_DIR, \\"01_target_order\\")\\n",\n    "dev = y - prior_in\\n",\n    "print(f\\"Simpangan target dari kurva isotonik in-sample: std {dev.std():.2f} (target std {y.std():.2f})\\")\\n",\n    "print(f\\"20% baris pertama: rata-rata {y[pos <= 0.2].mean():.1f}, std {y[pos <= 0.2].std():.1f} | 80% sisanya: rata-rata {y[pos > 0.2].mean():.1f}, std {y[pos > 0.2].std():.1f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "34474299",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Target turun hampir monoton dari awal sampai akhir file. Kurva isotonik in-sample menyisakan simpangan dengan std hanya 2,36, padahal std target 12,89: urutan baris sendirian menjelaskan sekitar 97% varians. Bagian awal file paling sulit: 20% baris pertama punya rata-rata 69,3 dan sebaran terbesar, termasuk nilai ekstrem sampai 100, sedangkan 80% sisanya rata-rata 46,7 dan jauh lebih rapat di sekitar kurva."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "b47994a2",\n   "metadata": {},\n   "source": [\n    "### 3.2 Fitur berkorelasi lemah dengan target, dan korelasinya mengikuti urutan baris"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "2d6c8aad",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "corr = pd.DataFrame({\\n",\n    "    \\"dengan target\\": [spearmanr(train[c], y).correlation for c in FEATURES],\\n",\n    "    \\"dengan posisi baris\\": [spearmanr(train[c], pos).correlation for c in FEATURES],\\n",\n    "}, index=FEATURES).sort_values(\\"dengan target\\")\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(13, 5.2), gridspec_kw={\\"width_ratios\\": [1.3, 1]})\\n",\n    "corr.plot.barh(ax=ax[0], color=[C1, C2], width=0.8)\\n",\n    "ax[0].axvline(0, color=CN, lw=1); ax[0].set(xlabel=\\"korelasi Spearman\\", title=\\"Korelasi tiap fitur\\"); ax[0].legend(fontsize=8)\\n",\n    "ax[1].scatter(corr[\\"dengan posisi baris\\"], corr[\\"dengan target\\"], color=C1)\\n",\n    "lim = np.abs(corr.values).max() * 1.1\\n",\n    "ax[1].plot([-lim, lim], [lim, -lim], ls=\\"--\\", color=CN, lw=1, label=\\"target = −posisi\\")\\n",\n    "ax[1].set(xlabel=\\"korelasi dengan posisi baris\\", ylabel=\\"korelasi dengan target\\", title=\\"Fitur membawa jejak urutan\\"); ax[1].legend()\\n",\n    "save_fig(FIG_DIR, \\"02_feature_corr\\")\\n",\n    "print(f\\"|korelasi| fitur terkuat dengan target: {corr[\'dengan target\'].abs().max():.3f} (posisi: {abs(rho_pos):.3f})\\")\\n",\n    "print(f\\"Korelasi antara kedua kolom korelasi: {np.corrcoef(corr[\'dengan target\'], corr[\'dengan posisi baris\'])[0, 1]:.3f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "7e025073",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Fitur dengan korelasi terkuat terhadap target hanya mencapai |0,42|, jauh di bawah posisi baris (0,98). Grafik kanan menunjukkan bahwa korelasi fitur dengan target hampir persis sama dengan negatif korelasinya dengan posisi (korelasi −0,999). Dengan kata lain, fitur hanya informatif karena fitur itu juga tersusun menurut urutan file. Inilah alasan tim memakai posisi sebagai prior dan fitur hanya sebagai koreksi."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "9d44cf9c",\n   "metadata": {},\n   "source": [\n    "### 3.3 Apakah test disusun dengan urutan yang sama?\\n",\n    "\\n",\n    "Prior posisi hanya berguna jika baris test juga diurutkan menurut target dengan cara yang sama. Target test tidak\\n",\n    "diketahui, jadi dua bukti tidak langsung dipakai: (1) model yang **hanya** memakai fitur, tanpa informasi posisi, dilatih di\\n",\n    "train lalu dipakai di test; jika prediksinya menurun terhadap urutan baris test, urutan test kemungkinan sama;\\n",\n    "(2) adversarial validation untuk melihat apakah train dan test berasal dari distribusi fitur yang sama."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "38541b25",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "# Model feature-only (jalur \\"strict\\" di notebook tim): 5-fold, blend NNLS dinormalisasi\\n",\n    "strict_oof = {}\\n",\n    "for tr, va in KFold(5, shuffle=True, random_state=SEED + 5).split(X):\\n",\n    "    for n, (p,) in fit_predict_models(X[tr], y[tr], [X[va]], SEED).items():\\n",\n    "        strict_oof.setdefault(n, np.zeros(n_train))[va] = p\\n",\n    "S = np.column_stack([strict_oof[n] for n in MODEL_NAMES])\\n",\n    "ws, _ = nnls(S, y); ws = ws / ws.sum()\\n",\n    "STRICT_OOF = S @ ws\\n",\n    "strict_full = fit_predict_models(X, y, [X_test], SEED)\\n",\n    "STRICT_TEST = np.column_stack([strict_full[n][0] for n in MODEL_NAMES]) @ ws\\n",\n    "rho_strict_tr = spearmanr(pos, STRICT_OOF).correlation\\n",\n    "rho_strict_te = spearmanr(pos_test, STRICT_TEST).correlation\\n",\n    "\\n",\n    "adv_X = np.vstack([X, X_test]); adv_y = np.r_[np.zeros(n_train), np.ones(n_test)]\\n",\n    "adv_p = cross_val_predict(RandomForestClassifier(300, min_samples_leaf=3, random_state=SEED), adv_X, adv_y,\\n",\n    "                          cv=StratifiedKFold(5, shuffle=True, random_state=SEED), method=\\"predict_proba\\")[:, 1]\\n",\n    "adv_auc = roc_auc_score(adv_y, adv_p)\\n",\n    "\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(13, 4.2))\\n",\n    "ax[0].scatter(pos, STRICT_OOF, s=12, color=C1, alpha=0.6, label=f\\"train, OOF (Spearman {rho_strict_tr:.2f})\\")\\n",\n    "ax[0].scatter(pos_test, STRICT_TEST, s=22, color=C2, marker=\\"s\\", alpha=0.8, label=f\\"test (Spearman {rho_strict_te:.2f})\\")\\n",\n    "ax[0].set(xlabel=\\"posisi baris (0 = awal file, 1 = akhir file)\\", ylabel=\\"prediksi model feature-only\\", title=\\"Prediksi dari fitur saja vs urutan baris\\"); ax[0].legend()\\n",\n    "ax[1].hist(adv_p[adv_y == 0], bins=25, alpha=0.6, density=True, color=C1, label=\\"train\\")\\n",\n    "ax[1].hist(adv_p[adv_y == 1], bins=25, alpha=0.6, density=True, color=C2, label=\\"test\\")\\n",\n    "ax[1].set(xlabel=\\"peluang \'baris test\' (OOF)\\", ylabel=\\"densitas\\", title=f\\"Adversarial validation, AUC {adv_auc:.3f}\\"); ax[1].legend()\\n",\n    "save_fig(FIG_DIR, \\"03_test_order\\")\\n",\n    "print(f\\"Feature-only OOF RMSE {rmse(y, STRICT_OOF):.4f} | bobot {dict(zip(MODEL_NAMES, ws.round(3)))}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "a241b017",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Model yang tidak pernah melihat posisi tetap menghasilkan prediksi test yang menurun terhadap urutan baris test (Spearman −0,75), hampir sama dengan pola di train (−0,80). Karena model hanya melihat fitur, pola ini berarti baris test kemungkinan besar diurutkan dengan cara yang sama seperti train. Adversarial validation memberi AUC 0,547, jadi distribusi fitur train dan test hampir sama. Kedua bukti ini membuat prior posisi layak dipakai untuk test, walaupun tetap merupakan asumsi tentang cara panitia menyusun file."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "4d469ec9",\n   "metadata": {},\n   "source": [\n    "## 4. Desain validasi\\n",\n    "\\n",\n    "Dengan hanya 382 baris dan target yang bergantung pada posisi, cara membagi fold menentukan angka yang dilaporkan. Tim\\n",\n    "memakai dua skema sekaligus:\\n",\n    "\\n",\n    "| Skema | Cara kerja | Yang diukur |\\n",\n    "| --- | --- | --- |\\n",\n    "| **Random repeated CV** (8 fold × 2 ulangan) | baris validasi berselang-seling dengan baris latih | situasi test, yang posisinya tersebar di sepanjang urutan |\\n",\n    "| **Blocked CV** (10 blok posisi) | satu blok posisi utuh ditahan | skenario terburuk: prior harus mengekstrapolasi ke blok yang tidak terlihat |\\n",\n    "\\n",\n    "Untuk mencegah kebocoran, label residual di setiap fold dihitung dari prior **out-of-fold di dalam fold latih**, bukan dari\\n",\n    "prior in-sample. Prior untuk baris validasi dihitung dari seluruh fold latih."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "742c6ea7",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "rand_splits = list(RepeatedKFold(n_splits=RANDOM_SPLITS, n_repeats=RANDOM_REPEATS, random_state=SEED + 1).split(X))\\n",\n    "blk_splits = block_splits(pos, N_BLOCKS)\\n",\n    "t1 = time.time()\\n",\n    "PR_R, RES_R = run_residual_cv(rand_splits, X, y, pos, INCREASING, SEED)\\n",\n    "PR_B, RES_B = run_residual_cv(blk_splits, X, y, pos, INCREASING, SEED)\\n",\n    "print(f\\"{len(rand_splits)} fold random + {len(blk_splits)} fold blocked selesai dalam {time.time() - t1:.0f} detik\\")\\n",\n    "tail20, body80 = pos <= 0.2, pos > 0.2"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "636d2d8c",\n   "metadata": {},\n   "source": [\n    "## 5. Baseline"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "af29726e",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "mean_r = np.zeros(n_train); c = np.zeros(n_train)\\n",\n    "for tr, va in rand_splits:\\n",\n    "    mean_r[va] += y[tr].mean(); c[va] += 1\\n",\n    "mean_r /= c\\n",\n    "mean_b = np.zeros(n_train)\\n",\n    "for tr, va in blk_splits:\\n",\n    "    mean_b[va] = y[tr].mean()\\n",\n    "RESULTS = {\\n",\n    "    \\"Rata-rata target\\": {\\"random CV\\": rmse(y, mean_r), \\"blocked CV\\": rmse(y, mean_b)},\\n",\n    "    \\"Model feature-only (tanpa posisi)\\": {\\"random CV\\": rmse(y, STRICT_OOF), \\"blocked CV\\": np.nan},\\n",\n    "    \\"Prior posisi saja\\": {\\"random CV\\": rmse(y, PR_R), \\"blocked CV\\": rmse(y, PR_B)},\\n",\n    "}\\n",\n    "pd.DataFrame(RESULTS).T.style.format(\\"{:.4f}\\", na_rep=\\"–\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "b586d3de",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Menebak rata-rata memberi RMSE 12,9. Model terbaik yang hanya memakai fitur menurunkannya ke 8,48. Prior posisi saja langsung mencapai 2,97 pada random CV, hampir tiga kali lebih baik dari model fitur. Pada blocked CV prior naik ke 4,43, karena harus mengekstrapolasi ke blok posisi yang tidak terlihat, terutama di awal file (RMSE 8,84 pada 20% baris pertama)."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "10af5307",\n   "metadata": {},\n   "source": [\n    "## 6. Residual learning\\n",\n    "\\n",\n    "Empat model mempelajari `residual = target − prior posisi` dari 24 fitur:\\n",\n    "\\n",\n    "| Model | Konfigurasi | Karakter |\\n",\n    "| --- | --- | --- |\\n",\n    "| `ridge` | StandardScaler + Ridge(α=100) | linear, sangat teregularisasi |\\n",\n    "| `svr_pca12` | StandardScaler + PCA(12, whiten) + SVR RBF | non-linear, tahan outlier |\\n",\n    "| `krr_raw` | StandardScaler + Kernel Ridge RBF | non-linear halus |\\n",\n    "| `gp_ard` | StandardScaler + Gaussian Process (Matern ν=2,5 dengan length-scale per fitur + white noise) | memilih fitur secara otomatis lewat length-scale |"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "62ec3953",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "rows = [{\\"model\\": \\"prior saja\\", \\"random CV\\": rmse(y, PR_R), \\"blocked CV\\": rmse(y, PR_B),\\n",\n    "         \\"blocked 20% awal\\": rmse(y[tail20], PR_B[tail20]), \\"blocked 80% sisanya\\": rmse(y[body80], PR_B[body80])}]\\n",\n    "for n in MODEL_NAMES:\\n",\n    "    pr, pb = PR_R + RES_R[n], PR_B + RES_B[n]\\n",\n    "    rows.append({\\"model\\": f\\"prior + {n}\\", \\"random CV\\": rmse(y, pr), \\"blocked CV\\": rmse(y, pb),\\n",\n    "                 \\"blocked 20% awal\\": rmse(y[tail20], pb[tail20]), \\"blocked 80% sisanya\\": rmse(y[body80], pb[body80])})\\n",\n    "cv_table = pd.DataFrame(rows).set_index(\\"model\\")\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(13, 3.8))\\n",\n    "for a, col, c_ in [(ax[0], \\"random CV\\", C1), (ax[1], \\"blocked CV\\", C2)]:\\n",\n    "    s = cv_table[col].sort_values(ascending=False)\\n",\n    "    a.barh(s.index, s.values, color=[CN if i == \\"prior saja\\" else c_ for i in s.index])\\n",\n    "    for i, v in enumerate(s.values):\\n",\n    "        a.text(v + 0.01, i, f\\"{v:.3f}\\", va=\\"center\\", fontsize=9)\\n",\n    "    a.set(xlim=(s.min() * 0.9, s.max() * 1.06), xlabel=\\"RMSE\\", title=col)\\n",\n    "save_fig(FIG_DIR, \\"04_residual_models\\")\\n",\n    "cv_table.style.format(\\"{:.4f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "679f39ca",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Di atas prior, GP-ARD memberi koreksi terbaik (random 2,250, blocked 4,398), disusul SVR+PCA12 dan Kernel Ridge. Ridge memperbaiki random CV sedikit tetapi memperburuk blocked CV, jadi hubungan residual dengan fitur tidak linear. Pada blocked CV semua model gagal memperbaiki 20% baris pertama secara berarti (8,67–8,89): nilai ekstrem di awal file tidak bisa dijelaskan fitur."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "d738a518",\n   "metadata": {},\n   "source": [\n    "## 7. Blending dan skala koreksi\\n",\n    "\\n",\n    "1. **NNLS** mencari bobot non-negatif untuk keempat residual yang meminimalkan galat pada gabungan OOF random dan blocked.\\n",\n    "2. Koreksi gabungan dikalikan skala `s` antara 0 dan 1,2. Tim memilih `s` dengan **blocked RMSE terendah**, lalu\\n",\n    "   membatasinya maksimal 1 agar koreksi tidak pernah diperbesar."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "413ddc29",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "w = nnls_blend([RES_R, RES_B], [y - PR_R, y - PR_B], MODEL_NAMES)\\n",\n    "blend_w = pd.Series(w, index=MODEL_NAMES)\\n",\n    "blend_R = np.column_stack([RES_R[n] for n in MODEL_NAMES]) @ w\\n",\n    "blend_B = np.column_stack([RES_B[n] for n in MODEL_NAMES]) @ w\\n",\n    "scale_df = pd.DataFrame({\\"skala\\": SCALES, \\"random CV\\": [rmse(y, PR_R + s * blend_R) for s in SCALES],\\n",\n    "                         \\"blocked CV\\": [rmse(y, PR_B + s * blend_B) for s in SCALES]})\\n",\n    "RES_SCALE = min(float(scale_df.sort_values(\\"blocked CV\\").iloc[0][\\"skala\\"]), 1.0)\\n",\n    "FINAL_R, FINAL_B = PR_R + RES_SCALE * blend_R, PR_B + RES_SCALE * blend_B\\n",\n    "RESULTS[f\\"Prior + {RES_SCALE} × blend residual (akhir)\\"] = {\\"random CV\\": rmse(y, FINAL_R), \\"blocked CV\\": rmse(y, FINAL_B)}\\n",\n    "\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(13, 4))\\n",\n    "blend_w.plot.barh(ax=ax[0], color=C1); ax[0].set(xlabel=\\"bobot NNLS\\", title=\\"Bobot blend residual\\")\\n",\n    "ax2 = ax[1].twinx()\\n",\n    "ax[1].plot(scale_df[\\"skala\\"], scale_df[\\"random CV\\"], \\"o-\\", color=C1, label=\\"random CV\\")\\n",\n    "ax2.plot(scale_df[\\"skala\\"], scale_df[\\"blocked CV\\"], \\"s-\\", color=C2, label=\\"blocked CV\\")\\n",\n    "ax[1].axvline(RES_SCALE, color=CN, ls=\\":\\", lw=1.2)\\n",\n    "ax[1].set(xlabel=\\"skala koreksi s\\", ylabel=\\"RMSE random CV\\", title=f\\"Memilih skala koreksi (terpilih {RES_SCALE})\\")\\n",\n    "ax2.set_ylabel(\\"RMSE blocked CV\\"); ax2.grid(False)\\n",\n    "h1, l1 = ax[1].get_legend_handles_labels(); h2, l2 = ax2.get_legend_handles_labels(); ax[1].legend(h1 + h2, l1 + l2, loc=\\"upper center\\")\\n",\n    "save_fig(FIG_DIR, \\"05_blend_scale\\")\\n",\n    "print(\\"Bobot NNLS:\\", blend_w.round(4).to_dict(), \\"| RES_SCALE:\\", RES_SCALE)\\n",\n    "print(f\\"Prior saja   random {rmse(y, PR_R):.4f} | blocked {rmse(y, PR_B):.4f}\\")\\n",\n    "print(f\\"Model akhir  random {rmse(y, FINAL_R):.4f} | blocked {rmse(y, FINAL_B):.4f} | gain blocked {rmse(y, PR_B) - rmse(y, FINAL_B):.4f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "90cc18c1",\n   "metadata": {},\n   "source": [\n    "**Temuan.** NNLS memberi bobot 0,565 untuk GP-ARD dan 0,307 untuk SVR+PCA12, dan 0 untuk Ridge serta KRR. Random CV terus membaik sampai skala 1,2, tetapi blocked CV mencapai minimum di skala 0,7 lalu naik lagi; tim memilih 0,7 agar koreksi tidak berlebihan. Hasilnya random CV 2,966 → 2,394 dan blocked CV 4,429 → 4,308."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "4726982d",\n   "metadata": {},\n   "source": [\n    "## 8. Diagnostik\\n",\n    "\\n",\n    "### 8.1 Di bagian urutan mana koreksi membantu?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "aae3d451",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "dec = np.minimum((pos * 10).astype(int), 9)\\n",\n    "rep = pd.DataFrame([{\\"desil posisi\\": d, \\"n\\": int((dec == d).sum()), \\"prior (blocked)\\": rmse(y[dec == d], PR_B[dec == d]),\\n",\n    "                     \\"akhir (blocked)\\": rmse(y[dec == d], FINAL_B[dec == d]), \\"akhir (random)\\": rmse(y[dec == d], FINAL_R[dec == d])}\\n",\n    "                    for d in range(10)]).set_index(\\"desil posisi\\")\\n",\n    "rep[\\"gain blocked\\"] = rep[\\"prior (blocked)\\"] - rep[\\"akhir (blocked)\\"]\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(13, 4.2))\\n",\n    "rep[[\\"prior (blocked)\\", \\"akhir (blocked)\\", \\"akhir (random)\\"]].plot.bar(ax=ax[0], color=[CN, C2, C1], width=0.8)\\n",\n    "ax[0].set(yscale=\\"log\\", xlabel=\\"desil posisi (0 = 10% baris pertama)\\", ylabel=\\"RMSE (log)\\", title=\\"RMSE per desil posisi\\"); ax[0].tick_params(axis=\\"x\\", rotation=0)\\n",\n    "ax[1].scatter(y, FINAL_R, s=14, alpha=0.6, color=C1, label=\\"random OOF\\")\\n",\n    "ax[1].scatter(y, FINAL_B, s=14, alpha=0.6, color=C2, label=\\"blocked OOF\\")\\n",\n    "ax[1].plot([y.min(), y.max()], [y.min(), y.max()], \\"--\\", color=CN, lw=1)\\n",\n    "ax[1].set(xlabel=\\"target asli\\", ylabel=\\"prediksi OOF\\", title=\\"Aktual vs prediksi model akhir\\"); ax[1].legend()\\n",\n    "save_fig(FIG_DIR, \\"06_deciles\\")\\n",\n    "print(\\"Desil yang membaik pada blocked CV:\\", int((rep[\\"gain blocked\\"] > 0).sum()), \\"/ 10\\")\\n",\n    "rep.style.format({c: \\"{:.3f}\\" for c in rep.columns if c != \\"n\\"})"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "37660c80",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Koreksi memperbaiki 7 dari 10 desil posisi pada blocked CV, dengan gain terbesar di desil 1–3 (0,46–0,75). Desil 0, 7, dan 9 sedikit memburuk. Desil 0 (10% baris pertama) tetap jauh lebih sulit daripada yang lain: RMSE blocked sekitar 11,9 dan random 5,2, dibanding 0,7–3,5 untuk desil lain. Grafik kanan memperlihatkan bahwa nilai target tertinggi diprediksi terlalu rendah, terutama pada blocked CV."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "de6338c2",\n   "metadata": {},\n   "source": [\n    "## 9. Submission\\n",\n    "\\n",\n    "Label residual untuk fit akhir memakai prior OOF seluruh train (10 fold × 5 ulangan), prior test dihitung dari seluruh\\n",\n    "train pada posisi baris test, lalu `prediksi = prior_test + RES_SCALE × blend residual`. Prediksi di-clip ke\\n",\n    "`[min(target) − 2, max(target) + 2]`."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "6b920b47",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "full_res_target = y - full_oof_prior(pos, y, INCREASING)\\n",\n    "PRIOR_TEST = prior_predict(pos, y, pos_test, INCREASING)\\n",\n    "full_preds = fit_predict_models(X, full_res_target, [X_test], SEED)\\n",\n    "res_test = np.column_stack([full_preds[n][0] for n in MODEL_NAMES]) @ w\\n",\n    "FINAL_TEST = np.clip(PRIOR_TEST + RES_SCALE * res_test, y.min() - 2, y.max() + 2)\\n",\n    "sub = pd.DataFrame({ID: test[ID].values, \\"prediction\\": FINAL_TEST})\\n",\n    "assert len(sub) == n_test and sub[ID].is_unique and np.isfinite(sub.prediction).all()\\n",\n    "sub.to_csv(OUT_DIR / \\"submission.csv\\", index=False)\\n",\n    "pd.DataFrame(RESULTS).T.to_csv(OUT_DIR / \\"cv_results.csv\\")\\n",\n    "cv_table.to_csv(OUT_DIR / \\"residual_models.csv\\"); scale_df.to_csv(OUT_DIR / \\"scale_scan.csv\\", index=False)\\n",\n    "pd.DataFrame({ID: test[ID].values, \\"posisi\\": pos_test, \\"prior\\": PRIOR_TEST, \\"koreksi\\": RES_SCALE * res_test,\\n",\n    "              \\"akhir\\": FINAL_TEST, \\"feature_only\\": STRICT_TEST}).to_csv(OUT_DIR / \\"test_decomposition.csv\\", index=False)\\n",\n    "\\n",\n    "fig, ax = plt.subplots(figsize=(12, 4))\\n",\n    "ax.plot(np.arange(n_test), PRIOR_TEST, color=CN, lw=2, label=\\"prior posisi\\")\\n",\n    "ax.plot(np.arange(n_test), FINAL_TEST, \\"o-\\", ms=3, color=C2, lw=1, label=\\"prediksi akhir\\")\\n",\n    "ax.plot(np.arange(n_test), STRICT_TEST, color=C1, alpha=0.6, label=\\"model feature-only\\")\\n",\n    "ax.set(xlabel=\\"urutan baris di test.csv\\", ylabel=\\"prediksi\\", title=\\"Prediksi test: prior, koreksi, dan model feature-only\\"); ax.legend()\\n",\n    "save_fig(FIG_DIR, \\"07_test_predictions\\")\\n",\n    "print(f\\"Rata-rata |koreksi| di test: {np.abs(RES_SCALE * res_test).mean():.3f} | korelasi koreksi dengan prediksi feature-only − prior: \\"\\n",\n    "      f\\"{np.corrcoef(res_test, STRICT_TEST - PRIOR_TEST)[0, 1]:.3f}\\")\\n",\n    "pd.DataFrame(RESULTS).T.style.format(\\"{:.4f}\\", na_rep=\\"–\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "7fa01187",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Koreksi residual di test rata-rata hanya 0,81 poin, sehingga prediksi akhir hampir mengikuti prior posisi, dengan penyesuaian terbesar di 15 baris pertama. Koreksi itu hampir tidak berkorelasi (0,05) dengan selisih model feature-only terhadap prior, jadi residual model memakai informasi yang berbeda dari model fitur biasa."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "35e1752e",\n   "metadata": {},\n   "source": [\n    "## 10. Kesimpulan\\n",\n    "\\n",\n    "1. **Urutan file adalah sinyal utama.** Spearman posisi vs target −0,981, sedangkan fitur terkuat hanya 0,42, dan korelasi fitur dengan target hanyalah cermin korelasinya dengan posisi.\\n",\n    "2. **Fitur tetap berguna sebagai koreksi.** Residual learning dengan label prior out-of-fold menurunkan random CV dari 2,966 ke 2,394 tanpa bocor, dan blend diredam ke 0,7× berdasarkan blocked CV.\\n",\n    "3. **Awal file adalah titik lemah.** 10% baris pertama memuat target tertinggi dan paling bervariasi; di sana prior dan fitur sama-sama gagal (RMSE blocked sekitar 12).\\n",\n    "4. **Hasil leaderboard.** Public 2,248 (sesuai random CV 2,394) tetapi private 3,081. Public hanya 29 baris, jadi selisih ini wajar jika private memuat lebih banyak baris dari awal file yang sulit; dugaan ini tidak bisa diverifikasi karena pembagian public/private tidak dipublikasikan. Tim finis peringkat 4 dari 13.\\n",\n    "\\n",\n    "**Keterbatasan.** Seluruh metode bergantung pada asumsi bahwa baris test diurutkan seperti train. Buktinya kuat tetapi tidak langsung. Jika urutan tidak boleh dipakai, model feature-only (RMSE 8,48) adalah gambaran jujur dari informasi yang ada di fitur.\\n",\n    "\\n",\n    "### Jejak lingkungan"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "a4a8776a",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import platform\\n",\n    "pkgs = [\\"numpy\\", \\"pandas\\", \\"scikit-learn\\", \\"scipy\\", \\"matplotlib\\", \\"seaborn\\"]\\n",\n    "print(\\" | \\".join([f\\"python {platform.python_version()}\\"] + [f\\"{p} {version(p)}\\" for p in pkgs]))\\n",\n    "print(f\\"Waktu eksekusi total: {(time.time() - T0) / 60:.1f} menit\\")"\n   ]\n  }\n ],\n "metadata": {\n  "kernelspec": {\n   "display_name": "Python 3",\n   "language": "python",\n   "name": "python3"\n  },\n  "language_info": {\n   "name": "python",\n   "version": "3.11"\n  }\n },\n "nbformat": 4,\n "nbformat_minor": 5\n}')

